package com.steven.assets.bff.portfolioadvice;
import com.steven.assets.bff.apierrorlogs.ApiErrorLogIngestClient;import com.steven.assets.bff.security.BusinessUserClient;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.context.ApplicationContext;import org.springframework.test.context.TestPropertySource;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.reactive.server.WebTestClient;import static org.mockito.Mockito.*;import static org.springframework.security.test.web.reactive.server.SecurityMockServerConfigurers.*;
@SpringBootTest @TestPropertySource(properties="business-services.url=http://127.0.0.1:1")
class SrppClaudeAuthSecurityTest {
 @Autowired ApplicationContext context;@MockitoBean BusinessUserClient users;@MockitoBean ApiErrorLogIngestClient ingest;
 @Test void securityBeforeControllerAndParameterFailuresAreNoStoreWithoutAuthorityOrIngestion(){reset(users,ingest);var client=WebTestClient.bindToApplicationContext(context).apply(springSecurity()).configureClient().build();String path="/api/bff/portfolio-advice/srpp/ai-auth/claude";client.get().uri(path+"/state?toolId=claude").exchange().expectStatus().isUnauthorized().expectHeader().valueEquals("Cache-Control","no-store");client.mutateWith(mockUser().roles("ADMIN")).get().uri(path+"/state").exchange().expectStatus().isBadRequest().expectHeader().valueEquals("Cache-Control","no-store");client.mutateWith(mockUser().roles("ADMIN")).post().uri(path+"/start").header("Content-Type","application/json").bodyValue("{\"toolId\":\"claude\"}").exchange().expectStatus().isForbidden().expectHeader().valueEquals("Cache-Control","no-store");verifyNoInteractions(users,ingest);}
}
